def count_prefixes(words, s):
    count = 0
    for word in words:
        # If the word is longer than s, it can't be a prefix
        if len(word) > len(s):
            continue

        # Assume it's a prefix
        is_prefix = True

        # Compare each character
        for i in range(len(word)):
            if word[i] != s[i]:
                is_prefix = False
                break

        if is_prefix:
            count += 1
    return count
